mapper.select:
select
*
from b_xiecheng_data
where  status =1 and push_status =1 and local_id = #{localId}

  and id > #{minId}

order by id asc limit 15000;

select * from b_xiecheng_data where status =1 and push_status =2 and sha256_tel = #{cell} and api_code in
#{apiCode}
and create_time > str_to_date(now(), '%Y-%m-%d')

select
  *
from b_xiecheng_data
where  create_date =#{createDate} and local_id not in (2242481,2242482,2272503)

  and local_id > #{minlocalId}

order by local_id limit 5000;
